import React, { useState } from 'react';

const logo = {
  alt: 'Old Mate Cranes & Rigging',
  url: 'logo01.png',
  width: 240,
  href: 'http://oldmatecranes.com.au/'
};

const menu = {
  link1:{
    copy:'home',
    url: 'http://localhost:3000/'
  },
  link2:{
    copy:'about us',
    url:'#aboutus'
  },
  link3:{
    copy:'contact',
    url: '#contact'
  },
  link4:{
    copy:'services',
    url:'#services'
  },
  link5:{
    copy:'safety',
    url: '#safety'
  },
  link6:{
    copy:'industrial',
    url:'#industrial'
  },
  link7:{
    copy:'civil',
    url:'#civil'
  }
};






const Menu = () => {
  const[isOpen ,setIsOpen] = useState(false);
  const toggle = () => setIsOpen (!isOpen);
  return (

  <section>
        <nav className='navbar navbar-expand-lg bg-body-tertiary fixed-top' role='navigation'>
          <div className='container-fluid'>
            <a className='navbar-brand' href={logo.href}>
            <img src={logo.url} alt={logo.alt} width={logo.width} />
            </a>
            <button className='navbar-toggler' type='button' data-bs-toggle='collapse' data-bs-target='#navbarSupportedContent' aria-controls='navbarSupportedContent' aria-expanded='false' aria-label='Toggle navigation'>
              <span className='navbar-toggler-icon'></span>
            </button>
            <div className='collapse navbar-collapse flex-row-reverse' id='navbarSupportedContent'>
              <div className='navbar-nav ml-auto menu-links'>
                <li className='nav-item'><a className='nav-link' href={menu.link1.url} style={{display: isOpen ? "block" : "none"}}>{menu.link1.copy}</a></li>
                <li className='nav-item'><a className='nav-link' href={menu.link2.url} style={{display: isOpen ? "block" : "none"}}>{menu.link2.copy}</a></li>
                <li className='nav-item'><a className='nav-link' href={menu.link3.url} style={{display: isOpen ? "block" : "none"}}>{menu.link3.copy}</a></li>
                <li className='nav-item'><a className='nav-link' href={menu.link4.url} style={{display: isOpen ? "block" : "none"}}>{menu.link4.copy}</a></li>
              </div>
            </div>
          </div>
        </nav>

      </section>
)};

export default Menu;
